namespace Astronomy.MediaFactory.Core.KnowledgeFoundation.Catalog;
public sealed class AstronomyKnowledgeCatalog:IAstronomyKnowledgeCatalog
{ readonly IReadOnlyDictionary<AstronomyKnowledgeCatalogEntryId,AstronomyKnowledgeCatalogEntry> byId; public AstronomyKnowledgeCatalog(AstronomyKnowledgeCatalogSnapshot snapshot){Snapshot=snapshot??throw new ArgumentNullException(nameof(snapshot)); byId=Snapshot.Entries.ToDictionary(e=>e.Id);} public AstronomyKnowledgeCatalogSnapshot Snapshot{get;} public bool TryGet(AstronomyKnowledgeCatalogEntryId id,out AstronomyKnowledgeCatalogEntry entry)=>byId.TryGetValue(id,out entry!); public IReadOnlyList<AstronomyKnowledgeCatalogEntry> GetByKind(AstronomyKnowledgeCatalogEntryKind kind){ if(!Enum.IsDefined(kind)) throw new ArgumentOutOfRangeException(nameof(kind)); return kind switch{AstronomyKnowledgeCatalogEntryKind.Domain=>Snapshot.Domains,AstronomyKnowledgeCatalogEntryKind.PayloadFamily=>Snapshot.PayloadFamilies,AstronomyKnowledgeCatalogEntryKind.KnowledgeType=>Snapshot.KnowledgeTypes,AstronomyKnowledgeCatalogEntryKind.ValidationRule=>Snapshot.ValidationRules,AstronomyKnowledgeCatalogEntryKind.CrossDomainValidationRule=>Snapshot.CrossDomainValidationRules,AstronomyKnowledgeCatalogEntryKind.GraphValidationRule=>Snapshot.GraphValidationRules,AstronomyKnowledgeCatalogEntryKind.StatementKind=>Snapshot.StatementKinds,_=>throw new ArgumentOutOfRangeException(nameof(kind))}; }}
